// Package harnessless is a daemon-based Chrome DevTools Protocol bridge.
// It mirrors the Python harnessless design but adds Go-native concurrency:
// goroutines for I/O, sync.RWMutex for per-tab locking, a channel-based
// worker pool to cap Chrome concurrency, and channel-delivered CDP responses.
package harnessless

// ── CDP wire types ────────────────────────────────────────────────────────────

// CDPRequest is a message sent to Chrome over the CDP WebSocket.
type CDPRequest struct {
	ID        int                    `json:"id"`
	Method    string                 `json:"method"`
	Params    map[string]interface{} `json:"params,omitempty"`
	SessionID string                 `json:"sessionId,omitempty"`
}

// CDPResponse is a message received from Chrome over the CDP WebSocket.
// It is either a reply to a CDPRequest (ID set) or an unsolicited event
// (Method set, ID == 0).
type CDPResponse struct {
	ID        int                    `json:"id,omitempty"`
	Method    string                 `json:"method,omitempty"` // set for events
	Result    map[string]interface{} `json:"result,omitempty"`
	Error     *CDPError              `json:"error,omitempty"`
	Params    map[string]interface{} `json:"params,omitempty"` // set for events
	SessionID string                 `json:"sessionId,omitempty"`
}

// CDPError is the error payload returned by Chrome for failed CDP commands.
type CDPError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// ── Unix-socket protocol types ────────────────────────────────────────────────

// ClientRequest is sent by a client to the daemon over the Unix socket.
// Either Method (CDP passthrough) or Meta (daemon control) must be set.
type ClientRequest struct {
	// CDP passthrough fields
	Method    string                 `json:"method,omitempty"`
	Params    map[string]interface{} `json:"params,omitempty"`
	SessionID string                 `json:"session_id,omitempty"`

	// Daemon meta-command: "session", "set_session", "drain_events", "shutdown"
	Meta string `json:"meta,omitempty"`
}

// ClientResponse is sent from the daemon to a client over the Unix socket.
type ClientResponse struct {
	Result    interface{} `json:"result,omitempty"`
	Error     string      `json:"error,omitempty"`
	Events    []Event     `json:"events,omitempty"`
	SessionID string      `json:"session_id,omitempty"`
	OK        bool        `json:"ok,omitempty"`
	Shutdown  bool        `json:"_shutdown,omitempty"`
}

// Event is a CDP event captured by the daemon and buffered for clients.
type Event struct {
	Method    string                 `json:"method"`
	Params    map[string]interface{} `json:"params"`
	SessionID string                 `json:"session_id"`
}

// ── Browser model types ───────────────────────────────────────────────────────

// Target represents a Chrome DevTools Protocol target (page, iframe, worker…).
type Target struct {
	TargetID string `json:"targetId"`
	Type     string `json:"type"`
	Title    string `json:"title"`
	URL      string `json:"url"`
}

// PageInfo holds viewport, scroll, and document dimensions for the current page.
type PageInfo struct {
	URL   string  `json:"url"`
	Title string  `json:"title"`
	W     float64 `json:"w"`  // window.innerWidth
	H     float64 `json:"h"`  // window.innerHeight
	SX    float64 `json:"sx"` // window.scrollX
	SY    float64 `json:"sy"` // window.scrollY
	PW    float64 `json:"pw"` // document.documentElement.scrollWidth
	PH    float64 `json:"ph"` // document.documentElement.scrollHeight
}

// ── Constants ─────────────────────────────────────────────────────────────────

const (
	// SockPath is the Unix domain socket the daemon listens on.
	SockPath = "/tmp/harnessless.sock"
	// PidPath is where the daemon writes its process ID.
	PidPath = "/tmp/harnessless.pid"
	// LogPath is the daemon's log file.
	LogPath = "/tmp/harnessless.log"
	// MaxEvents is the maximum number of CDP events held in the ring buffer.
	MaxEvents = 500
	// WorkerCount is the size of the CDP worker pool (limits Chrome concurrency).
	WorkerCount = 4
)

// InternalPrefixes lists URL prefixes that identify browser-internal pages.
// These are excluded from normal tab enumeration.
var InternalPrefixes = []string{
	"chrome://",
	"chrome-untrusted://",
	"devtools://",
	"chrome-extension://",
	"about:",
}

// readOnlyMethods is the set of CDP methods that only query state and therefore
// acquire a tab read-lock rather than a write-lock.
var readOnlyMethods = map[string]bool{
	"Page.captureScreenshot": true,
	"Page.printToPDF":        true,
	"Runtime.evaluate":       true,
	"Target.getTargets":      true,
	"Target.getTargetInfo":   true,
	"DOM.getDocument":        true,
	"DOM.querySelector":      true,
	"DOM.querySelectorAll":   true,
}

package harnessless

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/gorilla/websocket"
)

// ── Daemon ────────────────────────────────────────────────────────────────────

// Daemon maintains a persistent CDP WebSocket connection to Chrome and
// dispatches client requests via a Unix domain socket.
//
// Concurrency model:
//
//	readPump goroutine  ─── reads all Chrome messages, routes to pending channels
//	WorkerCount goroutines ─ drain workerCh; each holds a per-tab RWMutex while
//	                         executing a CDP call, preventing data races across
//	                         concurrent writes or read/write pairs on the same tab
//	handleConn goroutines ─ one per Unix-socket client; serialize per-connection
//	                        sends and push jobs onto workerCh
type Daemon struct {
	// WebSocket to Chrome
	ws   *websocket.Conn
	wsMu sync.Mutex // serialises ws.WriteMessage calls

	// Monotonically increasing CDP message IDs
	msgID atomic.Int64

	// In-flight CDP requests: map[int64]chan *CDPResponse
	pending sync.Map

	// CDP event ring buffer
	eventsMu sync.RWMutex
	events   []Event

	// Tab registry with per-tab RWMutex
	tabMgr *TabManager

	// Default CDP session (attached at startup)
	sessionMu sync.RWMutex
	sessionID string

	// Worker pool: limits concurrent Chrome calls
	workerCh chan workerJob

	ctx    context.Context
	cancel context.CancelFunc

	logger *log.Logger
}

// workerJob bundles a client request with a channel for delivering the response.
type workerJob struct {
	req    ClientRequest
	respCh chan ClientResponse
}

// NewDaemon dials Chrome's CDP WebSocket endpoint and starts the read pump
// and worker-pool goroutines.
func NewDaemon(wsURL string) (*Daemon, error) {
	conn, _, err := websocket.DefaultDialer.Dial(wsURL, nil)
	if err != nil {
		return nil, fmt.Errorf("dial CDP WebSocket %s: %w", wsURL, err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	d := &Daemon{
		ws:       conn,
		events:   make([]Event, 0, MaxEvents),
		tabMgr:   NewTabManager(),
		workerCh: make(chan workerJob, WorkerCount*2),
		ctx:      ctx,
		cancel:   cancel,
		logger:   log.New(os.Stderr, "[daemon] ", log.LstdFlags|log.Lshortfile),
	}

	// Single goroutine owns all Chrome reads ─ no lock needed on reads.
	go d.readPump()

	// Fixed pool of workers serialises Chrome writes to the desired concurrency.
	for i := 0; i < WorkerCount; i++ {
		go d.worker()
	}

	return d, nil
}

// ── Read pump ─────────────────────────────────────────────────────────────────

// readPump is the single goroutine that reads from the Chrome WebSocket.
// It routes replies to pending-request channels and buffers events.
func (d *Daemon) readPump() {
	defer d.cancel() // cancel daemon context if Chrome connection drops
	for {
		_, raw, err := d.ws.ReadMessage()
		if err != nil {
			if d.ctx.Err() == nil {
				d.logger.Printf("WebSocket read error: %v", err)
			}
			return
		}

		var resp CDPResponse
		if err := json.Unmarshal(raw, &resp); err != nil {
			d.logger.Printf("unmarshal CDP message: %v", err)
			continue
		}

		if resp.Method != "" && resp.ID == 0 {
			// Unsolicited CDP event
			d.appendEvent(Event{
				Method:    resp.Method,
				Params:    resp.Params,
				SessionID: resp.SessionID,
			})
			continue
		}

		// Reply to a pending request ─ deliver via channel (non-blocking store).
		if ch, ok := d.pending.LoadAndDelete(int64(resp.ID)); ok {
			ch.(chan *CDPResponse) <- &resp
		}
	}
}

func (d *Daemon) appendEvent(e Event) {
	d.eventsMu.Lock()
	defer d.eventsMu.Unlock()
	if len(d.events) >= MaxEvents {
		// Ring-buffer: drop the oldest event.
		copy(d.events, d.events[1:])
		d.events = d.events[:len(d.events)-1]
	}
	d.events = append(d.events, e)
}

// ── CDP I/O ───────────────────────────────────────────────────────────────────

// sendCDP sends a CDP command and waits (up to 30 s) for Chrome's reply.
// It is safe for concurrent use: wsMu guards the write; the read is delivered
// via a dedicated channel by readPump.
func (d *Daemon) sendCDP(method string, params map[string]interface{}, sessionID string) (*CDPResponse, error) {
	id := d.msgID.Add(1)

	req := CDPRequest{
		ID:        int(id),
		Method:    method,
		Params:    params,
		SessionID: sessionID,
	}
	data, err := json.Marshal(req)
	if err != nil {
		return nil, fmt.Errorf("marshal CDP request: %w", err)
	}

	// Register the reply channel before writing (avoids a race where Chrome
	// replies before we store the channel).
	replyCh := make(chan *CDPResponse, 1)
	d.pending.Store(id, replyCh)

	d.wsMu.Lock()
	err = d.ws.WriteMessage(websocket.TextMessage, data)
	d.wsMu.Unlock()
	if err != nil {
		d.pending.Delete(id)
		return nil, fmt.Errorf("ws write (%s): %w", method, err)
	}

	select {
	case resp := <-replyCh:
		return resp, nil
	case <-time.After(30 * time.Second):
		d.pending.Delete(id)
		return nil, fmt.Errorf("CDP timeout: %s", method)
	case <-d.ctx.Done():
		return nil, fmt.Errorf("daemon shutting down")
	}
}

// ── Session management ────────────────────────────────────────────────────────

func (d *Daemon) getSession() string {
	d.sessionMu.RLock()
	defer d.sessionMu.RUnlock()
	return d.sessionID
}

func (d *Daemon) setSession(s string) {
	d.sessionMu.Lock()
	defer d.sessionMu.Unlock()
	d.sessionID = s
}

// attachFirstPage finds the first non-internal page target, attaches to it,
// enables core CDP domains, and registers the session + Tab.
func (d *Daemon) attachFirstPage() error {
	resp, err := d.sendCDP("Target.getTargets", nil, "")
	if err != nil {
		return err
	}
	if resp.Error != nil {
		return fmt.Errorf("Target.getTargets: %s", resp.Error.Message)
	}

	targets, _ := resp.Result["targetInfos"].([]interface{})
	for _, raw := range targets {
		m, _ := raw.(map[string]interface{})
		if typ, _ := m["type"].(string); typ != "page" {
			continue
		}
		url, _ := m["url"].(string)
		if isInternalURL(url) {
			continue
		}
		targetID, _ := m["targetId"].(string)
		title, _ := m["title"].(string)

		ar, err := d.sendCDP("Target.attachToTarget", map[string]interface{}{
			"targetId": targetID,
			"flatten":  true,
		}, "")
		if err != nil {
			return err
		}
		if ar.Error != nil {
			return fmt.Errorf("Target.attachToTarget: %s", ar.Error.Message)
		}

		sid, _ := ar.Result["sessionId"].(string)
		d.setSession(sid)

		// Register tab in manager
		tab := &Tab{TargetID: targetID, URL: url, Title: title, SessionID: sid}
		d.tabMgr.Add(tab)
		d.tabMgr.SetCurrent(targetID)

		// Enable the CDP domains we care about
		for _, domain := range []string{"Page", "DOM", "Runtime", "Network"} {
			//nolint:errcheck
			d.sendCDP(domain+".enable", nil, sid)
		}

		d.logger.Printf("attached to %q (targetID=%s session=%s)", url, targetID, sid)
		return nil
	}
	return fmt.Errorf("no real page target found")
}

// tabForRequest returns the Tab associated with a request's session ID, and
// whether the CDP method is read-only. Returns nil if the tab is not tracked.
func (d *Daemon) tabForRequest(req ClientRequest) (*Tab, bool) {
	sid := req.SessionID
	if sid == "" {
		sid = d.getSession()
	}
	tab := d.tabMgr.BySession(sid)
	return tab, readOnlyMethods[req.Method]
}

// ── Request handling ──────────────────────────────────────────────────────────

// handleRequest processes a single ClientRequest and returns its response.
// It is called exclusively from worker goroutines.
func (d *Daemon) handleRequest(req ClientRequest) ClientResponse {
	if req.Meta != "" {
		return d.handleMeta(req)
	}
	return d.handleCDP(req)
}

func (d *Daemon) handleMeta(req ClientRequest) ClientResponse {
	switch req.Meta {
	case "session":
		return ClientResponse{SessionID: d.getSession()}

	case "set_session":
		d.setSession(req.SessionID)
		return ClientResponse{OK: true}

	case "drain_events":
		d.eventsMu.Lock()
		evs := make([]Event, len(d.events))
		copy(evs, d.events)
		d.events = d.events[:0]
		d.eventsMu.Unlock()
		return ClientResponse{Events: evs}

	case "shutdown":
		defer d.cancel()
		return ClientResponse{OK: true, Shutdown: true}

	default:
		return ClientResponse{Error: "unknown meta command: " + req.Meta}
	}
}

func (d *Daemon) handleCDP(req ClientRequest) ClientResponse {
	// Determine which session to use
	sid := req.SessionID
	if sid == "" && !strings.HasPrefix(req.Method, "Target.") {
		sid = d.getSession()
	}

	// Acquire per-tab lock for the duration of the Chrome round-trip.
	// Read-only methods (screenshot, evaluate, …) take a shared lock so
	// multiple concurrent reads on the same tab can proceed in parallel.
	// Mutating methods take an exclusive write lock.
	if tab, isRead := d.tabForRequest(req); tab != nil {
		if isRead {
			tab.RLock()
			defer tab.RUnlock()
		} else {
			tab.Lock()
			defer tab.Unlock()
		}
	}

	resp, err := d.sendCDP(req.Method, req.Params, sid)
	if err != nil {
		return ClientResponse{Error: err.Error()}
	}
	if resp.Error != nil {
		// Auto-recover stale session: re-attach and retry once.
		if sid != "" && sid == d.getSession() &&
			strings.Contains(resp.Error.Message, "Session with given id not found") {
			d.logger.Printf("stale session %s – re-attaching", sid)
			if raErr := d.attachFirstPage(); raErr != nil {
				return ClientResponse{Error: "session expired; re-attach failed: " + raErr.Error()}
			}
			newSID := d.getSession()
			resp2, err2 := d.sendCDP(req.Method, req.Params, newSID)
			if err2 != nil {
				return ClientResponse{Error: err2.Error()}
			}
			if resp2.Error != nil {
				return ClientResponse{Error: resp2.Error.Message}
			}
			return ClientResponse{Result: resp2.Result}
		}
		return ClientResponse{Error: resp.Error.Message}
	}

	// Keep tab metadata fresh after navigations
	if req.Method == "Page.navigate" {
		if tab := d.tabMgr.BySession(sid); tab != nil {
			if u, ok := req.Params["url"].(string); ok {
				tab.UpdateInfo(u, tab.Title)
			}
		}
	}

	return ClientResponse{Result: resp.Result}
}

// ── Worker pool ───────────────────────────────────────────────────────────────

// worker is one of WorkerCount goroutines that drain the workerCh channel.
// The pool caps concurrency to prevent overwhelming Chrome with parallel calls.
func (d *Daemon) worker() {
	for {
		select {
		case job := <-d.workerCh:
			job.respCh <- d.handleRequest(job.req)
		case <-d.ctx.Done():
			return
		}
	}
}

// ── Unix socket server ────────────────────────────────────────────────────────

// handleConn reads newline-delimited JSON requests from a Unix-socket connection
// and writes corresponding responses back. Each connection is handled in its own
// goroutine; requests within a connection are serialised (one at a time).
func (d *Daemon) handleConn(conn net.Conn) {
	defer conn.Close()
	scanner := bufio.NewScanner(conn)
	for scanner.Scan() {
		var req ClientRequest
		if err := json.Unmarshal(scanner.Bytes(), &req); err != nil {
			writeJSON(conn, ClientResponse{Error: "bad request: " + err.Error()})
			continue
		}

		// Submit to worker pool; block until a worker picks it up or daemon stops.
		respCh := make(chan ClientResponse, 1)
		select {
		case d.workerCh <- workerJob{req: req, respCh: respCh}:
		case <-d.ctx.Done():
			return
		}

		resp := <-respCh
		writeJSON(conn, resp)

		if resp.Shutdown {
			return
		}
	}
}

// Serve attaches to the first Chrome page, starts the Unix socket listener,
// and blocks until the daemon context is cancelled.
func (d *Daemon) Serve() error {
	if err := d.attachFirstPage(); err != nil {
		d.logger.Printf("initial attach failed: %v (will retry on first request)", err)
	}

	os.Remove(SockPath) // remove stale socket if any

	ln, err := net.Listen("unix", SockPath)
	if err != nil {
		return fmt.Errorf("listen %s: %w", SockPath, err)
	}
	if err := os.Chmod(SockPath, 0o600); err != nil {
		d.logger.Printf("chmod %s: %v", SockPath, err)
	}

	if err := os.WriteFile(PidPath, []byte(fmt.Sprintf("%d\n", os.Getpid())), 0o600); err != nil {
		d.logger.Printf("write pid: %v", err)
	}

	d.logger.Printf("listening on %s (pid=%d workers=%d)", SockPath, os.Getpid(), WorkerCount)

	// Cleanup goroutine: close listener and remove socket/pid on shutdown.
	go func() {
		<-d.ctx.Done()
		ln.Close()
		d.ws.Close()
		os.Remove(SockPath)
		os.Remove(PidPath)
	}()

	for {
		conn, err := ln.Accept()
		if err != nil {
			if d.ctx.Err() != nil {
				return nil // clean shutdown
			}
			return fmt.Errorf("accept: %w", err)
		}
		go d.handleConn(conn)
	}
}

// ── Entry point ───────────────────────────────────────────────────────────────

// RunDaemon is called by cmd/daemon/main.go. It reads Chrome's WebSocket URL,
// creates a Daemon, wires up OS signal handling, and calls Serve.
func RunDaemon() error {
	// Redirect logs to file (errors also go to stderr).
	if lf, err := os.OpenFile(LogPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600); err == nil {
		log.SetOutput(lf)
		defer lf.Close()
	}

	if AlreadyRunning() {
		fmt.Fprintln(os.Stderr, "harnessless daemon is already running")
		return nil
	}

	wsURL, err := GetChromeWSURL()
	if err != nil {
		return fmt.Errorf("locate Chrome: %w", err)
	}
	log.Printf("connecting to Chrome at %s", wsURL)

	d, err := NewDaemon(wsURL)
	if err != nil {
		return fmt.Errorf("init daemon: %w", err)
	}

	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-sig
		log.Println("received shutdown signal")
		d.cancel()
	}()

	return d.Serve()
}

// ── Chrome discovery ──────────────────────────────────────────────────────────

// GetChromeWSURL reads Chrome's DevToolsActivePort file and constructs the
// CDP WebSocket URL. Requires Chrome to be running with remote debugging
// enabled (chrome://inspect/#remote-debugging checkbox).
func GetChromeWSURL() (string, error) {
	dir, err := chromeProfileDir()
	if err != nil {
		return "", err
	}
	data, err := os.ReadFile(filepath.Join(dir, "DevToolsActivePort"))
	if err != nil {
		return "", fmt.Errorf(
			"read DevToolsActivePort (%s): %w\n"+
				"Is Chrome running with remote debugging enabled?\n"+
				"  macOS/Linux: open chrome://inspect/#remote-debugging and tick the checkbox",
			dir, err,
		)
	}
	lines := strings.SplitN(strings.TrimSpace(string(data)), "\n", 2)
	if len(lines) < 2 {
		return "", fmt.Errorf("malformed DevToolsActivePort (got %d lines)", len(lines))
	}
	return fmt.Sprintf("ws://127.0.0.1:%s%s",
		strings.TrimSpace(lines[0]),
		strings.TrimSpace(lines[1]),
	), nil
}

func chromeProfileDir() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("home dir: %w", err)
	}
	switch runtime.GOOS {
	case "darwin":
		return filepath.Join(home, "Library/Application Support/Google/Chrome"), nil
	case "linux":
		return filepath.Join(home, ".config/google-chrome"), nil
	case "windows":
		return filepath.Join(home, "AppData/Local/Google/Chrome/User Data"), nil
	default:
		return "", fmt.Errorf("unsupported OS %q – set CHROME_PROFILE_DIR env var", runtime.GOOS)
	}
}

// AlreadyRunning returns true if a daemon is already listening on SockPath.
func AlreadyRunning() bool {
	conn, err := net.DialTimeout("unix", SockPath, time.Second)
	if err != nil {
		return false
	}
	conn.Close()
	return true
}

// ── Helpers ───────────────────────────────────────────────────────────────────

func isInternalURL(u string) bool {
	for _, pfx := range InternalPrefixes {
		if strings.HasPrefix(u, pfx) {
			return true
		}
	}
	return false
}

func writeJSON(conn net.Conn, v interface{}) {
	data, _ := json.Marshal(v)
	conn.Write(append(data, '\n')) //nolint:errcheck
}

package harnessless

import "sync"

// Tab represents a live browser tab with its own read/write mutex.
//
// The RWMutex enables fine-grained concurrency:
//   - Multiple goroutines may hold a read-lock simultaneously (e.g., two
//     concurrent screenshot+page_info calls on the same tab).
//   - Mutating operations (navigate, click, type) hold a write-lock, blocking
//     all other access to this tab until the mutation completes.
//
// This is per-tab, not global: operations on different tabs proceed in
// parallel regardless of what any single tab is doing.
type Tab struct {
	TargetID  string
	URL       string
	Title     string
	SessionID string

	mu sync.RWMutex // guards the fields above
}

// RLock acquires the tab's shared read lock.
func (t *Tab) RLock() { t.mu.RLock() }

// RUnlock releases the tab's shared read lock.
func (t *Tab) RUnlock() { t.mu.RUnlock() }

// Lock acquires the tab's exclusive write lock.
func (t *Tab) Lock() { t.mu.Lock() }

// Unlock releases the tab's exclusive write lock.
func (t *Tab) Unlock() { t.mu.Unlock() }

// UpdateInfo updates the tab's mutable metadata under the write lock.
func (t *Tab) UpdateInfo(url, title string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.URL = url
	t.Title = title
}

// Snapshot returns a copy of the tab's metadata under the read lock.
func (t *Tab) Snapshot() (targetID, url, title, sessionID string) {
	t.mu.RLock()
	defer t.mu.RUnlock()
	return t.TargetID, t.URL, t.Title, t.SessionID
}

// ── TabManager ────────────────────────────────────────────────────────────────

// TabManager maintains the registry of known tabs and the currently-active tab.
//
// The manager-level RWMutex guards the map and the current-target pointer.
// Per-Tab mutexes guard the Tab's own fields (URL, Title, SessionID).
//
// Concurrency guarantee: reading the map (Get, List, Current) is lock-free for
// readers; structural mutations (Add, Remove, SetCurrent) briefly write-lock.
type TabManager struct {
	mu      sync.RWMutex
	tabs    map[string]*Tab // key: TargetID
	current string          // TargetID of the active tab
}

// NewTabManager allocates an empty TabManager.
func NewTabManager() *TabManager {
	return &TabManager{tabs: make(map[string]*Tab)}
}

// Add registers a tab. If a tab with the same TargetID already exists it is
// replaced.
func (tm *TabManager) Add(tab *Tab) {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	tm.tabs[tab.TargetID] = tab
}

// Get retrieves a tab by its TargetID.  Returns (nil, false) if not found.
func (tm *TabManager) Get(targetID string) (*Tab, bool) {
	tm.mu.RLock()
	defer tm.mu.RUnlock()
	t, ok := tm.tabs[targetID]
	return t, ok
}

// BySession finds the tab whose SessionID matches sid.
// Returns nil if no matching tab exists.
func (tm *TabManager) BySession(sid string) *Tab {
	tm.mu.RLock()
	defer tm.mu.RUnlock()
	for _, t := range tm.tabs {
		if t.SessionID == sid {
			return t
		}
	}
	return nil
}

// List returns a snapshot of all registered tabs.  The returned slice is a
// copy; callers should not mutate it.
func (tm *TabManager) List() []*Tab {
	tm.mu.RLock()
	defer tm.mu.RUnlock()
	out := make([]*Tab, 0, len(tm.tabs))
	for _, t := range tm.tabs {
		out = append(out, t)
	}
	return out
}

// SetCurrent marks the tab with the given TargetID as active.
func (tm *TabManager) SetCurrent(targetID string) {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	tm.current = targetID
}

// Current returns the TargetID of the active tab, or "" if none is set.
func (tm *TabManager) Current() string {
	tm.mu.RLock()
	defer tm.mu.RUnlock()
	return tm.current
}

// CurrentTab returns the active Tab, or nil if none is set.
func (tm *TabManager) CurrentTab() *Tab {
	tm.mu.RLock()
	defer tm.mu.RUnlock()
	if tm.current == "" {
		return nil
	}
	return tm.tabs[tm.current]
}

// Remove deregisters a tab. If the tab was current, current is cleared.
func (tm *TabManager) Remove(targetID string) {
	tm.mu.Lock()
	defer tm.mu.Unlock()
	delete(tm.tabs, targetID)
	if tm.current == targetID {
		tm.current = ""
	}
}

package harnessless

import (
	"bufio"
	"encoding/json"
	"fmt"
	"net"
	"os"
	"os/exec"
	"time"
)

// Client is a thin connector to the harnessless daemon's Unix socket.
//
// Typical usage:
//
//	c := harnessless.NewClient()
//	if err := c.EnsureDaemon(0); err != nil { log.Fatal(err) }
//	h := harnessless.NewHelpers(c)
//	h.Goto("https://example.com")
//
// Each Send call opens a fresh connection so multiple goroutines may safely
// share a single Client (each call is independently serialised through its
// own connection).
type Client struct {
	sockPath string
}

// NewClient returns a Client pointed at the default socket path.
func NewClient() *Client {
	return &Client{sockPath: SockPath}
}

// NewClientAt returns a Client pointed at a custom socket path (useful for
// tests or running multiple daemons on the same machine).
func NewClientAt(sockPath string) *Client {
	return &Client{sockPath: sockPath}
}

// ── Low-level transport ───────────────────────────────────────────────────────

// Send delivers req to the daemon and returns the response.
// It opens a new connection for each call: this is intentionally stateless so
// that the caller does not need to manage connection lifetimes.
func (c *Client) Send(req ClientRequest) (ClientResponse, error) {
	conn, err := net.DialTimeout("unix", c.sockPath, 3*time.Second)
	if err != nil {
		return ClientResponse{}, fmt.Errorf("connect daemon (%s): %w", c.sockPath, err)
	}
	defer conn.Close()

	// Total round-trip deadline: CDP timeout (30 s) + a small buffer.
	conn.SetDeadline(time.Now().Add(35 * time.Second)) //nolint:errcheck

	data, err := json.Marshal(req)
	if err != nil {
		return ClientResponse{}, fmt.Errorf("marshal request: %w", err)
	}
	if _, err := conn.Write(append(data, '\n')); err != nil {
		return ClientResponse{}, fmt.Errorf("send request: %w", err)
	}

	scanner := bufio.NewScanner(conn)
	if !scanner.Scan() {
		if err := scanner.Err(); err != nil {
			return ClientResponse{}, fmt.Errorf("read response: %w", err)
		}
		return ClientResponse{}, fmt.Errorf("daemon closed connection without responding")
	}

	var resp ClientResponse
	if err := json.Unmarshal(scanner.Bytes(), &resp); err != nil {
		return ClientResponse{}, fmt.Errorf("unmarshal response: %w", err)
	}
	return resp, nil
}

// ── CDP passthrough ───────────────────────────────────────────────────────────

// CDP sends a raw CDP command through the daemon and returns the result map.
// Pass an empty sessionID to use the daemon's current default session.
func (c *Client) CDP(method string, sessionID string, params map[string]interface{}) (map[string]interface{}, error) {
	resp, err := c.Send(ClientRequest{Method: method, Params: params, SessionID: sessionID})
	if err != nil {
		return nil, err
	}
	if resp.Error != "" {
		return nil, fmt.Errorf("%s: %s", method, resp.Error)
	}
	result, _ := resp.Result.(map[string]interface{})
	return result, nil
}

// ── Session management ────────────────────────────────────────────────────────

// GetSession returns the daemon's current default CDP session ID.
func (c *Client) GetSession() (string, error) {
	resp, err := c.Send(ClientRequest{Meta: "session"})
	if err != nil {
		return "", err
	}
	return resp.SessionID, nil
}

// SetSession overwrites the daemon's default session ID.
// Use after SwitchTab or NewTab to make sure subsequent calls target the
// newly-active tab.
func (c *Client) SetSession(sessionID string) error {
	resp, err := c.Send(ClientRequest{Meta: "set_session", SessionID: sessionID})
	if err != nil {
		return err
	}
	if !resp.OK {
		return fmt.Errorf("set_session: daemon returned not-ok")
	}
	return nil
}

// ── Event buffer ──────────────────────────────────────────────────────────────

// DrainEvents atomically retrieves all buffered CDP events and clears the
// daemon's event queue.  Returns an empty (non-nil) slice if there are none.
func (c *Client) DrainEvents() ([]Event, error) {
	resp, err := c.Send(ClientRequest{Meta: "drain_events"})
	if err != nil {
		return nil, err
	}
	if resp.Events == nil {
		return []Event{}, nil
	}
	return resp.Events, nil
}

// ── Daemon lifecycle ──────────────────────────────────────────────────────────

// DaemonAlive returns true if the daemon accepts a connection within 1 second.
func (c *Client) DaemonAlive() bool {
	conn, err := net.DialTimeout("unix", c.sockPath, time.Second)
	if err != nil {
		return false
	}
	conn.Close()
	return true
}

// EnsureDaemon starts the daemon if it is not already running.
// It waits up to waitSecs for the daemon to become ready; 0 uses the default
// of 8 seconds.  EnsureDaemon is idempotent and safe to call on every script
// invocation.
//
// The daemon binary is assumed to be the same executable as the caller with
// the sub-command "daemon" (see cmd/daemon/main.go). Override by setting the
// HARNESSLESS_DAEMON env var to a custom path.
func (c *Client) EnsureDaemon(waitSecs float64) error {
	if c.DaemonAlive() {
		return nil
	}
	if waitSecs <= 0 {
		waitSecs = 8
	}

	daemonBin := os.Getenv("HARNESSLESS_DAEMON")
	if daemonBin == "" {
		// Default: look for a "harnessless-daemon" binary on PATH.
		var err error
		daemonBin, err = exec.LookPath("harnessless-daemon")
		if err != nil {
			return fmt.Errorf(
				"daemon not running and harnessless-daemon binary not found on PATH\n"+
					"  build it with: go build -o harnessless-daemon ./cmd/daemon\n"+
					"  or set HARNESSLESS_DAEMON=/path/to/binary",
			)
		}
	}

	cmd := exec.Command(daemonBin)
	cmd.Stdout = nil
	cmd.Stderr = nil
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("start daemon %s: %w", daemonBin, err)
	}

	deadline := time.Now().Add(time.Duration(waitSecs * float64(time.Second)))
	for time.Now().Before(deadline) {
		if c.DaemonAlive() {
			return nil
		}
		time.Sleep(200 * time.Millisecond)
	}
	return fmt.Errorf("daemon did not become ready within %.0f seconds", waitSecs)
}

// Shutdown requests the daemon to exit gracefully.
func (c *Client) Shutdown() error {
	_, err := c.Send(ClientRequest{Meta: "shutdown"})
	return err
}

package harnessless

import (
	"encoding/base64"
	"fmt"
	"os"
	"strings"
	"time"
)

// Helpers provides high-level, LLM-friendly browser automation methods.
// Every method is a thin wrapper over Client.CDP, mirroring the Python
// helpers.py design principle: ≤15 lines per function, transparent names,
// easy for a language model to read and edit at runtime.
//
// Create with NewHelpers(client).
type Helpers struct {
	c *Client
}

// NewHelpers wraps client with the high-level browser API.
func NewHelpers(c *Client) *Helpers {
	return &Helpers{c: c}
}

// cdp is a convenience shortcut that uses the daemon's default session.
func (h *Helpers) cdp(method string, params map[string]interface{}) (map[string]interface{}, error) {
	return h.c.CDP(method, "", params)
}

// cdpSID is a convenience shortcut that uses an explicit session ID.
func (h *Helpers) cdpSID(method, sid string, params map[string]interface{}) (map[string]interface{}, error) {
	return h.c.CDP(method, sid, params)
}

// ── Navigation ────────────────────────────────────────────────────────────────

// Goto navigates the active tab to url and waits for the page to finish loading.
func (h *Helpers) Goto(url string) error {
	if _, err := h.cdp("Page.navigate", map[string]interface{}{"url": url}); err != nil {
		return err
	}
	return h.WaitForLoad(15.0)
}

// WaitForLoad polls document.readyState until it is "complete" or timeout
// (in seconds) is exceeded.
func (h *Helpers) WaitForLoad(timeout float64) error {
	deadline := time.Now().Add(time.Duration(timeout * float64(time.Second)))
	for time.Now().Before(deadline) {
		res, err := h.cdp("Runtime.evaluate", map[string]interface{}{
			"expression":    "document.readyState",
			"returnByValue": true,
		})
		if err == nil {
			if result, ok := res["result"].(map[string]interface{}); ok {
				if result["value"] == "complete" {
					return nil
				}
			}
		}
		time.Sleep(300 * time.Millisecond)
	}
	return fmt.Errorf("page did not reach readyState=complete within %.0fs", timeout)
}

// PageInfo returns the current URL, title, viewport size, scroll position,
// and full document dimensions.
func (h *Helpers) PageInfo() (*PageInfo, error) {
	const expr = `(function(){return{
		url:   location.href,
		title: document.title,
		w:     window.innerWidth,
		h:     window.innerHeight,
		sx:    window.scrollX,
		sy:    window.scrollY,
		pw:    document.documentElement.scrollWidth,
		ph:    document.documentElement.scrollHeight
	}})()`
	res, err := h.cdp("Runtime.evaluate", map[string]interface{}{
		"expression":    expr,
		"returnByValue": true,
		"awaitPromise":  false,
	})
	if err != nil {
		return nil, err
	}
	rv, _ := res["result"].(map[string]interface{})
	val, _ := rv["value"].(map[string]interface{})

	info := &PageInfo{}
	info.URL, _ = val["url"].(string)
	info.Title, _ = val["title"].(string)
	info.W, _ = val["w"].(float64)
	info.H, _ = val["h"].(float64)
	info.SX, _ = val["sx"].(float64)
	info.SY, _ = val["sy"].(float64)
	info.PW, _ = val["pw"].(float64)
	info.PH, _ = val["ph"].(float64)
	return info, nil
}

// ── Mouse input ───────────────────────────────────────────────────────────────

// Click dispatches mousePressed + mouseReleased at (x, y).
// button is "left" (default), "middle", or "right".
// clicks is the clickCount (1 = single, 2 = double); 0 defaults to 1.
func (h *Helpers) Click(x, y float64, button string, clicks int) error {
	if button == "" {
		button = "left"
	}
	if clicks == 0 {
		clicks = 1
	}
	for _, typ := range []string{"mousePressed", "mouseReleased"} {
		_, err := h.cdp("Input.dispatchMouseEvent", map[string]interface{}{
			"type":       typ,
			"x":          x,
			"y":          y,
			"button":     button,
			"clickCount": clicks,
		})
		if err != nil {
			return fmt.Errorf("click (%s): %w", typ, err)
		}
	}
	return nil
}

// Scroll sends a mouseWheel event at (x, y).
// dy < 0 scrolls up; dy > 0 scrolls down.  Zero dy defaults to -300.
// dx controls horizontal scroll.
func (h *Helpers) Scroll(x, y, dy, dx float64) error {
	if dy == 0 && dx == 0 {
		dy = -300
	}
	_, err := h.cdp("Input.dispatchMouseEvent", map[string]interface{}{
		"type":   "mouseWheel",
		"x":      x,
		"y":      y,
		"deltaY": dy,
		"deltaX": dx,
	})
	return err
}

// ── Keyboard input ────────────────────────────────────────────────────────────

// TypeText inserts text directly into the focused element without simulating
// individual key events (faster than PressKey for bulk input).
func (h *Helpers) TypeText(text string) error {
	_, err := h.cdp("Input.insertText", map[string]interface{}{"text": text})
	return err
}

// PressKey dispatches keyDown + keyUp for a named key.
// modifiers is a bitmask: 1=Alt  2=Ctrl  4=Meta/Cmd  8=Shift.
// Common keys: "Enter", "Tab", "Escape", "Backspace", "ArrowDown", etc.
func (h *Helpers) PressKey(key string, modifiers int) error {
	for _, typ := range []string{"keyDown", "keyUp"} {
		_, err := h.cdp("Input.dispatchKeyEvent", map[string]interface{}{
			"type":      typ,
			"key":       key,
			"modifiers": modifiers,
		})
		if err != nil {
			return fmt.Errorf("key %s (%s): %w", key, typ, err)
		}
	}
	return nil
}

// ── Visual ────────────────────────────────────────────────────────────────────

// Screenshot captures the current page as a PNG and writes it to path.
// If path is empty, defaults to /tmp/shot.png.
// Set full=true to capture the entire scrollable document (not just viewport).
func (h *Helpers) Screenshot(path string, full bool) error {
	if path == "" {
		path = "/tmp/shot.png"
	}
	res, err := h.cdp("Page.captureScreenshot", map[string]interface{}{
		"format":                "png",
		"captureBeyondViewport": full,
	})
	if err != nil {
		return err
	}
	dataStr, _ := res["data"].(string)
	decoded, err := base64.StdEncoding.DecodeString(dataStr)
	if err != nil {
		return fmt.Errorf("base64 decode screenshot: %w", err)
	}
	return os.WriteFile(path, decoded, 0o644)
}

// ── JavaScript ────────────────────────────────────────────────────────────────

// JS evaluates a JavaScript expression in the active tab and returns the result.
// If targetID is non-empty, a fresh attachment is made to that target first.
// Async expressions (returning a Promise) are automatically awaited.
func (h *Helpers) JS(expression string, targetID string) (interface{}, error) {
	sid := ""
	if targetID != "" {
		res, err := h.cdpSID("Target.attachToTarget", "", map[string]interface{}{
			"targetId": targetID,
			"flatten":  true,
		})
		if err != nil {
			return nil, fmt.Errorf("attach %s: %w", targetID, err)
		}
		sid, _ = res["sessionId"].(string)
	}
	res, err := h.cdpSID("Runtime.evaluate", sid, map[string]interface{}{
		"expression":    expression,
		"returnByValue": true,
		"awaitPromise":  true,
	})
	if err != nil {
		return nil, err
	}
	rv, _ := res["result"].(map[string]interface{})
	return rv["value"], nil
}

// ── Tab management ────────────────────────────────────────────────────────────

// ListTabs returns all open page targets, optionally including chrome:// pages.
func (h *Helpers) ListTabs(includeChrome bool) ([]Target, error) {
	res, err := h.cdpSID("Target.getTargets", "", nil)
	if err != nil {
		return nil, err
	}
	rawList, _ := res["targetInfos"].([]interface{})
	var tabs []Target
	for _, raw := range rawList {
		m, _ := raw.(map[string]interface{})
		if typ, _ := m["type"].(string); typ != "page" {
			continue
		}
		url, _ := m["url"].(string)
		if !includeChrome && isInternalURL(url) {
			continue
		}
		tabs = append(tabs, Target{
			TargetID: strField(m, "targetId"),
			Type:     strField(m, "type"),
			Title:    strField(m, "title"),
			URL:      url,
		})
	}
	return tabs, nil
}

// CurrentTab returns target info for the tab the daemon is currently attached to.
func (h *Helpers) CurrentTab() (*Target, error) {
	res, err := h.cdp("Target.getTargetInfo", nil)
	if err != nil {
		return nil, err
	}
	ti, _ := res["targetInfo"].(map[string]interface{})
	return &Target{
		TargetID: strField(ti, "targetId"),
		URL:      strField(ti, "url"),
		Title:    strField(ti, "title"),
		Type:     strField(ti, "type"),
	}, nil
}

// SwitchTab attaches the daemon to targetID and updates the default session.
func (h *Helpers) SwitchTab(targetID string) error {
	res, err := h.cdpSID("Target.attachToTarget", "", map[string]interface{}{
		"targetId": targetID,
		"flatten":  true,
	})
	if err != nil {
		return err
	}
	sid, _ := res["sessionId"].(string)
	return h.c.SetSession(sid)
}

// NewTab opens a new browser tab at url and switches to it.
// Pass an empty url to open about:blank.
func (h *Helpers) NewTab(url string) (*Target, error) {
	if url == "" {
		url = "about:blank"
	}
	res, err := h.cdpSID("Target.createTarget", "", map[string]interface{}{"url": url})
	if err != nil {
		return nil, err
	}
	targetID, _ := res["targetId"].(string)
	if err := h.SwitchTab(targetID); err != nil {
		return nil, fmt.Errorf("switch to new tab: %w", err)
	}
	return &Target{TargetID: targetID, URL: url}, nil
}

// EnsureRealTab re-attaches the daemon if the current tab is an internal page
// or the session is stale.
func (h *Helpers) EnsureRealTab() error {
	t, err := h.CurrentTab()
	if err != nil || isInternalURL(t.URL) {
		tabs, listErr := h.ListTabs(false)
		if listErr != nil {
			return listErr
		}
		if len(tabs) == 0 {
			return fmt.Errorf("no real tabs available")
		}
		return h.SwitchTab(tabs[0].TargetID)
	}
	return nil
}

// IframeTarget finds the first iframe-type target whose URL contains substr.
func (h *Helpers) IframeTarget(substr string) (*Target, error) {
	res, err := h.cdpSID("Target.getTargets", "", nil)
	if err != nil {
		return nil, err
	}
	rawList, _ := res["targetInfos"].([]interface{})
	for _, raw := range rawList {
		m, _ := raw.(map[string]interface{})
		url, _ := m["url"].(string)
		if strings.Contains(url, substr) {
			return &Target{
				TargetID: strField(m, "targetId"),
				Type:     strField(m, "type"),
				Title:    strField(m, "title"),
				URL:      url,
			}, nil
		}
	}
	return nil, fmt.Errorf("no iframe target containing %q", substr)
}

// ── Events ────────────────────────────────────────────────────────────────────

// DrainEvents returns all CDP events buffered since the last call and clears
// the buffer.  Thin alias over Client.DrainEvents for convenience.
func (h *Helpers) DrainEvents() ([]Event, error) {
	return h.c.DrainEvents()
}

// ── Utilities ─────────────────────────────────────────────────────────────────

// Wait pauses execution for seconds.
func (h *Helpers) Wait(seconds float64) {
	time.Sleep(time.Duration(seconds * float64(time.Second)))
}

// Client returns the underlying Client for raw CDP access.
func (h *Helpers) Client() *Client { return h.c }

// ── internal ──────────────────────────────────────────────────────────────────

func strField(m map[string]interface{}, key string) string {
	s, _ := m[key].(string)
	return s
}

// Command harnessless-client is a command-line interface for the harnessless
// daemon. It provides one subcommand per browser action so shell scripts and
// LLM tool-calls can drive Chrome without writing Go code.
//
// Usage:
//
//	harnessless-client <command> [args...]
//
// Commands:
//
//	goto   <url>              Navigate the active tab
//	click  <x> <y>            Left-click at (x, y)
//	dclick <x> <y>            Double-click at (x, y)
//	rclick <x> <y>            Right-click at (x, y)
//	type   <text>             Insert text into focused element
//	key    <key> [modifiers]  Press a named key (Enter, Tab, Escape, …)
//	scroll <x> <y> [dy] [dx] Scroll at (x, y); dy negative = up
//	shot   [path] [full]      Screenshot → path (default /tmp/shot.png)
//	info                      Print URL, title, viewport, scroll as JSON
//	js     <expr>             Evaluate JavaScript, print result
//	tabs                      List open tabs as JSON
//	tab    <targetId>         Switch to a tab by target ID
//	newtab [url]              Open a new tab (default about:blank)
//	events                    Drain and print buffered CDP events
//	cdp    <method> [json]    Raw CDP passthrough
//	alive                     Exit 0 if daemon is alive, 1 otherwise
//	shutdown                  Ask the daemon to exit
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"strconv"

	harnessless "github.com/browser-use/go-harnessless"
)

func main() {
	log.SetFlags(0)
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, usage)
		os.Exit(1)
	}

	c := harnessless.NewClient()
	h := harnessless.NewHelpers(c)
	cmd := os.Args[1]
	args := os.Args[2:]

	switch cmd {
	// ── Navigation ──────────────────────────────────────────────────────────
	case "goto":
		need(cmd, args, 1)
		die(h.Goto(args[0]))

	// ── Mouse ────────────────────────────────────────────────────────────────
	case "click":
		need(cmd, args, 2)
		x, y := mustFloat(args[0]), mustFloat(args[1])
		die(h.Click(x, y, "left", 1))

	case "dclick":
		need(cmd, args, 2)
		x, y := mustFloat(args[0]), mustFloat(args[1])
		die(h.Click(x, y, "left", 2))

	case "rclick":
		need(cmd, args, 2)
		x, y := mustFloat(args[0]), mustFloat(args[1])
		die(h.Click(x, y, "right", 1))

	case "scroll":
		need(cmd, args, 2)
		x, y := mustFloat(args[0]), mustFloat(args[1])
		dy, dx := -300.0, 0.0
		if len(args) >= 3 {
			dy = mustFloat(args[2])
		}
		if len(args) >= 4 {
			dx = mustFloat(args[3])
		}
		die(h.Scroll(x, y, dy, dx))

	// ── Keyboard ─────────────────────────────────────────────────────────────
	case "type":
		need(cmd, args, 1)
		die(h.TypeText(args[0]))

	case "key":
		need(cmd, args, 1)
		mods := 0
		if len(args) >= 2 {
			mods = int(mustFloat(args[1]))
		}
		die(h.PressKey(args[0], mods))

	// ── Visual ───────────────────────────────────────────────────────────────
	case "shot":
		path := ""
		full := false
		if len(args) >= 1 {
			path = args[0]
		}
		if len(args) >= 2 {
			full = (args[1] == "true" || args[1] == "1")
		}
		die(h.Screenshot(path, full))
		if path == "" {
			path = "/tmp/shot.png"
		}
		fmt.Println(path)

	// ── Page info ────────────────────────────────────────────────────────────
	case "info":
		info, err := h.PageInfo()
		die(err)
		printJSON(info)

	// ── JavaScript ───────────────────────────────────────────────────────────
	case "js":
		need(cmd, args, 1)
		val, err := h.JS(args[0], "")
		die(err)
		printJSON(val)

	// ── Tab management ───────────────────────────────────────────────────────
	case "tabs":
		tabs, err := h.ListTabs(false)
		die(err)
		printJSON(tabs)

	case "tab":
		need(cmd, args, 1)
		die(h.SwitchTab(args[0]))

	case "newtab":
		url := ""
		if len(args) >= 1 {
			url = args[0]
		}
		t, err := h.NewTab(url)
		die(err)
		printJSON(t)

	// ── Events ───────────────────────────────────────────────────────────────
	case "events":
		evs, err := h.DrainEvents()
		die(err)
		printJSON(evs)

	// ── Raw CDP ──────────────────────────────────────────────────────────────
	case "cdp":
		need(cmd, args, 1)
		var params map[string]interface{}
		if len(args) >= 2 {
			if err := json.Unmarshal([]byte(args[1]), &params); err != nil {
				log.Fatalf("invalid JSON params: %v", err)
			}
		}
		result, err := c.CDP(args[0], "", params)
		die(err)
		printJSON(result)

	// ── Daemon control ───────────────────────────────────────────────────────
	case "alive":
		if c.DaemonAlive() {
			fmt.Println("alive")
			os.Exit(0)
		}
		fmt.Fprintln(os.Stderr, "daemon not running")
		os.Exit(1)

	case "shutdown":
		die(c.Shutdown())

	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n\n%s\n", cmd, usage)
		os.Exit(1)
	}
}

// ── helpers ───────────────────────────────────────────────────────────────────

func die(err error) {
	if err != nil {
		log.Fatalf("error: %v", err)
	}
}

func need(cmd string, args []string, n int) {
	if len(args) < n {
		log.Fatalf("%s requires %d argument(s), got %d", cmd, n, len(args))
	}
}

func mustFloat(s string) float64 {
	v, err := strconv.ParseFloat(s, 64)
	if err != nil {
		log.Fatalf("expected a number, got %q: %v", s, err)
	}
	return v
}

func printJSON(v interface{}) {
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		log.Fatalf("encode JSON: %v", err)
	}
}

