// Command harnessless-daemon starts the harnessless CDP bridge daemon.
//
// The daemon:
//   - Connects to your already-running Chrome via the DevTools Protocol
//   - Listens on a Unix socket for client requests
//   - Multiplexes requests through a worker pool so Chrome is never overloaded
//
// Prerequisites:
//
//	Chrome must be running with remote debugging enabled.
//	Enable it at: chrome://inspect/#remote-debugging
//	(tick "Discover network targets" / enable remote debugging checkbox)
//
// Usage:
//
//	harnessless-daemon
//
// The daemon writes logs to /tmp/harnessless.log and its PID to
// /tmp/harnessless.pid.  It exits cleanly on SIGINT or SIGTERM.
package main

import (
	"log"

	harnessless "github.com/browser-use/go-harnessless"
)

func main() {
	if err := harnessless.RunDaemon(); err != nil {
		log.Fatalf("daemon error: %v", err)
	}
}
